import re
from datetime import datetime

_DIGITS = "0123456789"
_DISPLAY_NAME_RE = re.compile(r"<([^<>]*)>")
_ZIP_PLUS4_RE = re.compile(r"[0-9]{4,5}-[0-9]{4}")
_TAG_SPLIT_RE = re.compile(r"[;,]")
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}


def _norm_email(raw):
    """Return the normalized email, or "" if it is not valid."""
    s = raw.strip()
    m = _DISPLAY_NAME_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    if s.count("@") != 1:
        return ""
    local, domain = s.split("@")
    if local and "." in domain and not domain.startswith(".") and not domain.endswith("."):
        return s
    return ""


def _norm_phone(raw):
    """Return the normalized 10-digit phone, or "" if it is not valid."""
    s = raw.lower()
    cut = len(s)
    for marker in ("x", "ext", "#"):
        i = s.find(marker)
        if i != -1 and i < cut:
            cut = i
    digits = "".join(c for c in s[:cut] if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _norm_zip(raw):
    """Return the normalized 5-digit ZIP, or "" if it is not valid."""
    s = raw.strip()
    if _ZIP_PLUS4_RE.fullmatch(s):
        s = s.split("-", 1)[0]
    if len(s) == 4 and all(c in _DIGITS for c in s):
        s = "0" + s
    if len(s) == 5 and all(c in _DIGITS for c in s):
        return s
    return ""


def _norm_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def dedupe_contacts(rows):
    # 1. Normalize each row and drop rows with neither a valid email nor a valid phone.
    recs = []
    for row in rows:
        email = _norm_email(row.get("email", ""))
        phone = _norm_phone(row.get("phone", ""))
        if not email and not phone:
            continue
        source = row.get("source", "").strip().lower()
        recs.append({
            "first_name": _norm_name(row.get("first_name", "")),
            "last_name": _norm_name(row.get("last_name", "")),
            "zip": _norm_zip(row.get("zip", "")),
            "email": email,
            "phone": phone,
            "source": source,
            "manual": source == "manual",
            "tags": {
                t.strip().lower()
                for t in _TAG_SPLIT_RE.split(row.get("tags", ""))
                if t.strip()
            },
            "opted_out": row.get("opted_out", "").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(row["updated"]),
        })

    # 2. Union-find: link rows that share a valid email, or a valid phone plus last name.
    n = len(recs)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    first_by_email = {}
    first_by_phone_last = {}
    for k, r in enumerate(recs):
        if r["email"]:
            if r["email"] in first_by_email:
                union(k, first_by_email[r["email"]])
            else:
                first_by_email[r["email"]] = k
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].casefold())
            if key in first_by_phone_last:
                union(k, first_by_phone_last[key])
            else:
                first_by_phone_last[key] = k

    groups = {}
    for k in range(n):
        groups.setdefault(find(k), []).append(k)

    # 3. Build one output dict per person, ordered by earliest input row.
    def pick(ranked, field):
        for k in ranked:
            if recs[k][field]:
                return recs[k][field]
        return ""

    people = []
    for members in sorted(groups.values(), key=lambda m: m[0]):
        # Preference: manual rows first, then latest "updated", then earliest input row.
        ranked = sorted(members)
        ranked = sorted(ranked, key=lambda k: recs[k]["updated"], reverse=True)
        ranked = sorted(ranked, key=lambda k: 0 if recs[k]["manual"] else 1)

        tags = set()
        for k in members:
            tags |= recs[k]["tags"]

        people.append({
            "first_name": pick(ranked, "first_name"),
            "last_name": pick(ranked, "last_name"),
            "zip": pick(ranked, "zip"),
            "email": pick(ranked, "email"),
            "phone": pick(ranked, "phone"),
            "source": pick(ranked, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(recs[k]["opted_out"] for k in members) else "N",
            "updated": max(recs[k]["updated"] for k in members).strftime("%Y-%m-%d"),
        })

    return people
